@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-analytics-frame {
  position: relative;
  display: grid;
  width: 100%;
  min-width: 0;
  gap: 9px;
  margin: 0;
}

.whatiuse-analytics-frame__header {
  display: flex;
  min-width: 0;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.whatiuse-analytics-frame__header > div { display: grid; min-width: 0; gap: 2px; }

.whatiuse-analytics-frame__header h3 { margin: 0; color: var(--whatiuse-fg-default); font-size: var(--whatiuse-type-ui); font-weight: 600; letter-spacing: -.014em; }

.whatiuse-analytics-frame__header p { margin: 0; color: var(--whatiuse-fg-muted); font-size: var(--whatiuse-type-metadata); line-height: 1.35; }

.whatiuse-analytics-frame__data-toggle {
  min-height: 28px;
  flex: none;
  padding: 0 8px;
  border: 0;
  border-radius: var(--whatiuse-radius-control);
  background: transparent;
  color: var(--whatiuse-fg-muted);
  font: inherit;
  font-size: var(--whatiuse-type-metadata);
  cursor: pointer;
  transition: background-color var(--whatiuse-hover-duration) var(--whatiuse-ease-out), color var(--whatiuse-hover-duration) var(--whatiuse-ease-out);
}

.whatiuse-analytics-frame__data-toggle:disabled { color: var(--whatiuse-fg-subtle); cursor: default; opacity: .58; }

.whatiuse-analytics-frame__data-toggle:focus { outline: 0; }

.whatiuse-analytics-frame__stage {
  position: relative;
  min-width: 0;
  min-height: var(--whatiuse-analytics-height);
}

.whatiuse-analytics-frame__stage > [hidden] { display: none; }

.whatiuse-analytics-frame__inspection { min-width: 0; }

.whatiuse-analytics-tooltip {
  position: absolute;
  z-index: 4;
  top: 52px;
  right: 8px;
  width: min(228px, calc(100% - 16px));
  opacity: 0;
  pointer-events: none;
  transition: opacity 90ms var(--whatiuse-ease-out), visibility 0s linear 90ms;
  visibility: hidden;
}

.whatiuse-analytics-tooltip[data-pointer-positioned] {
  top: 0;
  right: auto;
  left: 0;
}

.whatiuse-analytics-tooltip:has(.whatiuse-analytics-inspection[data-active]) {
  opacity: 1;
  transition-delay: 0s;
  visibility: visible;
}

.whatiuse-analytics-tooltip .whatiuse-analytics-inspection {
  display: grid;
  width: 100%;
  min-height: 0;
  justify-content: stretch;
  gap: 6px;
  padding: 8px 10px;
  border: 1px solid color-mix(in oklch, var(--whatiuse-border-strong) 58%, transparent);
  border-radius: 8px;
  background: var(--whatiuse-bg-flyout);
  box-shadow: var(--whatiuse-shadow-flyout);
}

.whatiuse-analytics-tooltip .whatiuse-analytics-inspection__items {
  display: grid;
  width: 100%;
  gap: 4px;
}

.whatiuse-analytics-tooltip .whatiuse-analytics-inspection__item {
  display: grid;
  width: 100%;
  grid-template-columns: 6px minmax(0, 1fr) auto;
  gap: 6px;
}

.whatiuse-analytics-tooltip .whatiuse-analytics-inspection__item > span {
  overflow: hidden;
  text-overflow: ellipsis;
}

.whatiuse-analytics-inspection {
  display: flex;
  min-width: 0;
  min-height: 34px;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0 10px;
  border-radius: 7px;
  background: color-mix(in oklch, var(--whatiuse-bg-stage) 78%, transparent);
  color: var(--whatiuse-fg-subtle);
  font-size: var(--whatiuse-type-metadata);
  font-variant-numeric: tabular-nums;
  transition: background-color 120ms var(--whatiuse-ease-out), color 120ms var(--whatiuse-ease-out);
}

.whatiuse-analytics-inspection > strong {
  min-width: 0;
  overflow: hidden;
  color: var(--whatiuse-fg-muted);
  font-weight: 560;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.whatiuse-analytics-inspection[data-active] > strong { color: var(--whatiuse-fg-default); }

.whatiuse-analytics-inspection__items {
  display: inline-flex;
  min-width: 0;
  flex: none;
  align-items: center;
  gap: 12px;
}

.whatiuse-analytics-inspection__item {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
}

.whatiuse-analytics-inspection__item > i {
  width: 6px;
  height: 6px;
  flex: none;
  border-radius: 50%;
  background: var(--whatiuse-fg-default);
}

.whatiuse-analytics-inspection__item[data-tone="secondary"] > i { opacity: .62; }

.whatiuse-analytics-inspection__item[data-tone="tertiary"] > i { opacity: .34; }

.whatiuse-analytics-inspection__item > b { color: var(--whatiuse-fg-default); font-weight: 570; }

@media (max-width: 640px) {
.whatiuse-analytics-inspection { gap: 10px; }

.whatiuse-analytics-inspection__items { gap: 8px; }

.whatiuse-analytics-inspection__item > span { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
}

@media (prefers-reduced-motion: reduce) {
.whatiuse-analytics-inspection { transition-duration: 0ms; }

.whatiuse-analytics-tooltip { transition-duration: 0ms; }
}

.whatiuse-analytics-frame__plot {
  position: relative;
  height: var(--whatiuse-analytics-height);
  min-width: 0;
  overflow: hidden;
  border-radius: var(--whatiuse-radius-container);
  background: var(--whatiuse-bg-surface);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--whatiuse-control-border) 58%, transparent), 0 1px 2px rgb(17 17 19 / .025);
}

.whatiuse-analytics-frame__table {
  width: 100%;
  min-width: 0;
  height: var(--whatiuse-analytics-height);
  overflow: auto;
  border-radius: var(--whatiuse-radius-container);
  background: var(--whatiuse-bg-stage);
}

.whatiuse-analytics-frame__table table { width: 100%; border-collapse: collapse; font-size: var(--whatiuse-type-metadata); font-variant-numeric: tabular-nums; }

.whatiuse-analytics-frame__table caption { padding: 10px 12px; text-align: left; color: var(--whatiuse-fg-default); font-weight: 590; }

.whatiuse-analytics-frame__table th,
.whatiuse-analytics-frame__table td { padding: 8px 12px; border-top: 1px solid var(--whatiuse-separator); text-align: right; white-space: nowrap; }

.whatiuse-analytics-frame__table th:first-child { text-align: left; }

.whatiuse-analytics-frame__table thead th { color: var(--whatiuse-fg-subtle); font-weight: 540; }

.whatiuse-analytics-frame__table tbody th { color: var(--whatiuse-fg-muted); font-weight: 520; }

.whatiuse-analytics-frame__state {
  display: grid;
  height: var(--whatiuse-analytics-height);
  place-content: center;
  grid-auto-flow: column;
  align-items: center;
  gap: 8px;
  border-radius: var(--whatiuse-radius-container);
  background: var(--whatiuse-bg-surface);
  color: var(--whatiuse-fg-subtle);
  font-size: var(--whatiuse-type-ui);
}

.whatiuse-analytics-frame__state[role="alert"] { color: var(--whatiuse-fg-danger); }

.whatiuse-analytics-frame__state > span { width: 12px; height: 12px; border: 1.5px solid var(--whatiuse-separator-strong); border-top-color: var(--whatiuse-fg-default); border-radius: 50%; animation: whatiuse-spinner .7s linear infinite; }

@media (hover: hover) and (pointer: fine) {
.whatiuse-analytics-frame__data-toggle:not(:disabled):hover { background: var(--whatiuse-hover); color: var(--whatiuse-fg-default); }
}

@media (prefers-reduced-motion: reduce) {
.whatiuse-analytics-frame__data-toggle { transition-duration: 0ms; }

.whatiuse-analytics-frame__state > span { animation: none; }
}

.whatiuse-analytics-interactive-plot { position: relative; width: 100%; height: 100%; outline: 0; }

.whatiuse-analytics-interactive-plot > svg { display: block; width: 100%; height: 100%; overflow: visible; }

.whatiuse-chart__table--visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; }

@keyframes whatiuse-spin { to { transform: rotate(360deg); } }
}
